// N3.JS ZONDER DE DELEN DIE DEZE APP NIET KENT — de smalle barrel.
//
// `n3/src/index.js` exporteert dertien dingen. De app gebruikt er zes, en dat is
// mechanisch vastgesteld en mechanisch bewaakt (tools/shim-n3.test.mjs): over
// heel `src/` komen alleen `N3.DataFactory`, `N3.Store`, `N3.Parser`,
// `N3.Writer`, `N3.termFromId` en `N3.termToId` voor — als member-toegang of via
// `const { … } = N3`.
//
// WAAROM DE BARREL NIET VANZELF WEGSNOEIT. n3 draagt `"sideEffects": false`, dus
// in theorie zou Rollup `Reasoner`, `StreamParser`, `StreamWriter` en
// `StoreFactory` moeten laten vallen. In de praktijk doet hij dat niet volledig:
// gemeten op de stand vóór deze huls stonden `N3Reasoner` (3.932 bytes),
// `N3StreamWriter` (1.539) en `N3StreamParser` in de INSTAPCHUNK. Elf modules
// in `src/` doen `import * as N3 from 'n3'`, en een namespace-object dat door
// meerdere modules heen reist is voor Rollup niet in alle gevallen tot een vaste
// set properties te herleiden.
//
// DE HULS NEEMT DIE TWIJFEL WEG door de barrel te vervangen door precies de zes
// namen. Wat er niet in staat, kan niet meereizen — en wie er een zevende nodig
// heeft, krijgt een `undefined` op de aanroepplek en zet hem hier erbij. Dat is
// een zichtbare stap, en dat is de bedoeling.
//
// VOLGORDE VAN DE HULZEN. Deze werkt samen met tools/shim-node-stream.mjs: die
// haalt de node-streamlaag uit `N3Store`/`N3Lexer`, deze haalt de ongebruikte
// N3-modules eruit. Ze zijn onafhankelijk — elk mag los weg.
export { default as DataFactory, termFromId, termToId } from 'n3/src/N3DataFactory.js';
export { default as Store } from 'n3/src/N3Store.js';
export { default as Parser } from 'n3/src/N3Parser.js';
export { default as Writer } from 'n3/src/N3Writer.js';

// `import * as N3` levert een namespace-object; een default-export erbij maakt
// ook `import N3 from 'n3'` mogelijk, zoals de echte barrel dat doet.
import DataFactoryD, { termFromId as tFi, termToId as tTi } from 'n3/src/N3DataFactory.js';
import StoreD from 'n3/src/N3Store.js';
import ParserD from 'n3/src/N3Parser.js';
import WriterD from 'n3/src/N3Writer.js';

export default {
  DataFactory: DataFactoryD, Store: StoreD, Parser: ParserD, Writer: WriterD,
  termFromId: tFi, termToId: tTi,
};
