// `buffer` UIT DE BROWSERBUNDEL — de tweelingbroer van shim-node-stream.mjs.
//
// De volledige verantwoording staat daar; hier alleen wat eigen is aan deze
// huls. N3Lexer importeert `Buffer` op moduleniveau en gebruikt hem op precies
// één plek: `Buffer.concat([this._pendingBuffer, data])`, in de tak waar de
// invoer een STREAM is die byte-chunks levert. De app voert de lexer altijd een
// string; die tak draait niet.
//
// De `buffer`-package zelf weegt 24.743 gebouwde bytes en sleept `base64-js` en
// `ieee754` mee — alle drie in de instap én in de worker-chunk.
//
// `isBuffer` geeft `false` in plaats van te gooien: dat is een VRAAG, geen
// gebruik, en het antwoord is hier per constructie onwaar. De rest gooit.

const REDEN = 'Buffer: deze app voert de N3-lexer altijd een string, dus staat'
  + ' de buffer-polyfill niet in de browserbundel (tools/shim-node-buffer.mjs).'
  + ' Wie hier komt, geeft byte-chunks aan N3 — voeg de polyfill dan terug toe.';

function gooi() { throw new Error(REDEN); }

export const Buffer = {
  isBuffer: () => false,
  concat: gooi,
  from: gooi,
  alloc: gooi,
  allocUnsafe: gooi,
  byteLength: gooi,
};

export const kMaxLength = 0;
export const INSPECT_MAX_BYTES = 50;

export default { Buffer, kMaxLength, INSPECT_MAX_BYTES };
